import React from 'react';
import {AbsoluteFill, useS, en, T, idx, interpolate, Easing, clamp, golpe, DUR} from './kit';

export const SUBS = {arriba: 230, acento: '#f1ce8d'};

const F = (s: number, t: number, d = 1) => interpolate(s, [t, t + d], [0, 1], {...clamp, easing: Easing.inOut(Easing.sin)});
const mix = (a: [number, number], b: [number, number], t: number): [number, number] => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
const md = (v: number, m: number) => ((v % m) + m) % m;
const SK = '#c79a73';

// ---------- Fuego y lámparas ----------
const Flame: React.FC<{x: number; y: number; s: number; i: number; k?: number}> = ({x, y, s, i, k = 1}) => {
  const f = Math.sin(s * 9 + i * 2) * 0.5 + Math.sin(s * 13.7 + i) * 0.5;
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <ellipse rx={70} ry={90} cy={-30} fill="url(#glowW)" opacity={0.6 + 0.15 * f} />
      <path d={`M0 0Q-13 -16 -6 -34Q${-2 + f * 3} -48 ${f * 4} -64Q${6 + f * 3} -44 8 -32Q15 -16 0 0Z`} fill="#ffb347" />
      <path d={`M0 -2Q-6 -12 -2 -26Q0 -36 ${1 + f * 2} -42Q5 -28 4 -20Q6 -10 0 -2Z`} fill="#fff3b0" />
    </g>
  );
};
const Lamp: React.FC<{x: number; y: number; s: number; i: number}> = ({x, y, s, i}) => (
  <g>
    <path d={`M${x - 24} ${y}Q${x - 28} ${y - 16} ${x - 8} ${y - 18}H${x + 12}Q${x + 40} ${y - 22} ${x + 48} ${y - 30}Q${x + 42} ${y - 4} ${x + 22} ${y + 2}Q${x} ${y + 10} ${x - 24} ${y}Z`} fill="#b5793c" stroke="#e3b074" strokeWidth={2} />
    <Flame x={x + 46} y={y - 30} s={s} i={i} />
  </g>
);

// ---------- Personajes ----------
type TP = {s: number; cross?: number; raise?: number; chest?: number; ext?: number; palms?: number; kneel?: number; look?: number; turn?: number; dir?: number; walk?: number; eyes?: number; wind?: number};
const Tomas: React.FC<TP> = ({s, cross = 0, raise = 0, chest = 0, ext = 0, palms = 0, kneel = 0, look = 0, turn = 0, dir = 1, walk = 0, eyes = 1, wind = 0}) => {
  const k = kneel * 150;
  const br = Math.sin(s * 1.6) * 3;
  const bob = -walk * Math.abs(Math.sin(s * 4.4)) * 12;
  const sway = Math.sin(s * 1.1) * 3 + wind * Math.sin(s * 5) * 5;
  let L: [number, number] = [-92, -230];
  let R: [number, number] = [92, -230];
  L = mix(L, [42, -312], cross);
  R = mix(R, [-42, -300], cross);
  L = mix(L, [-72, -286], palms);
  R = mix(R, [72, -286], palms);
  R = mix(R, [150, -565], raise);
  L = mix(L, [-22, -352], chest);
  R = mix(R, [22, -352], chest);
  R = mix(R, [122, -388], ext);
  const hy = (h: [number, number]): [number, number] => [h[0], h[1] + k * 0.92 + br * 0.5];
  const Lh = hy(L), Rh = hy(R);
  const arm = (sx: number, h: [number, number], side: number) => `M${sx} ${-392 + k} Q${(sx + h[0]) / 2 + side * 38} ${(-392 + k + h[1]) / 2 + 34} ${h[0]} ${h[1]}`;
  const hand = (h: [number, number], key: string) => (
    <g key={key}>
      <circle cx={h[0]} cy={h[1]} r={21 + palms * 4} fill={SK} stroke="#e8c9a8" strokeWidth={2} />
      {palms > 0.3 && <circle cx={h[0]} cy={h[1]} r={13} fill="#e2bb98" opacity={palms} />}
    </g>
  );
  const hem = 125 + kneel * 30;
  return (
    <g transform={`scale(${dir} 1)`}>
      <ellipse cy={10} rx={150} ry={26} fill="#000" opacity={0.28} />
      {wind > 0.01 && (
        <path d={`M-55 ${-395 + k}Q${-120 - wind * 60} ${-380 + Math.sin(s * 7) * wind * 20} ${-170 - wind * 110} ${-300 + Math.sin(s * 6 + 1) * wind * 40}L${-150 - wind * 90} ${-220 + Math.sin(s * 5) * wind * 30}Q-100 -290 -62 -300Z`} fill="#b48226" opacity={0.95} />
      )}
      <g transform={`translate(${sway * 0.5} 0)`}>
        <path d={`M-62 ${-405 + k}Q-98 ${-200 + k * 0.5} ${-hem} -6Q0 16 ${hem} -6Q98 ${-200 + k * 0.5} 62 ${-405 + k}Q0 ${-434 + k} -62 ${-405 + k}Z`} fill="url(#tRobe)" stroke="#f3d489" strokeWidth={2.5} strokeOpacity={0.5} />
        <path d={`M-62 ${-405 + k}Q-98 ${-200 + k * 0.5} ${-hem} -6Q0 16 ${hem} -6Q98 ${-200 + k * 0.5} 62 ${-405 + k}Q0 ${-434 + k} -62 ${-405 + k}Z`} fill="url(#shade)" />
        <path d={`M-36 ${-330 + k}Q-44 -150 -56 -10M0 ${-340 + k}Q0 -150 0 -4M36 ${-330 + k}Q44 -150 56 -10`} stroke="#5d3f10" strokeOpacity={0.22} strokeWidth={4} fill="none" />
        <path d={`M-74 ${-262 + k * 0.6}Q0 ${-244 + k * 0.6} 74 ${-262 + k * 0.6}`} stroke="#6b4a1a" strokeWidth={15} fill="none" strokeLinecap="round" />
        <path d={`M-24 ${-405 + k}L0 ${-352 + k}L24 ${-405 + k}Z`} fill="#efe3c6" />
        {kneel < 0.5 && [-38, 38].map((x) => <ellipse key={x} cx={x} cy={9} rx={34} ry={13} fill="#4a3322" />)}
        <path d={arm(-58, Lh, -1)} stroke="#b17f26" strokeWidth={42} strokeLinecap="round" fill="none" />
        <path d={arm(-58, Lh, -1)} stroke="#f0cc78" strokeOpacity={0.3} strokeWidth={9} strokeLinecap="round" fill="none" />
        <path d={arm(58, Rh, 1)} stroke="#b17f26" strokeWidth={42} strokeLinecap="round" fill="none" />
        <path d={arm(58, Rh, 1)} stroke="#f0cc78" strokeOpacity={0.3} strokeWidth={9} strokeLinecap="round" fill="none" />
        {hand(Lh, 'l')}
        {hand(Rh, 'r')}
        <g transform={`translate(0 ${-540 + k + br * 0.4 + bob}) rotate(${turn + look * 9})`}>
          <rect x={-18} y={42} width={36} height={34} rx={10} fill="#a87a56" />
          <ellipse cx={-50} cy={2} rx={9} ry={14} fill="#b68460" />
          <ellipse cx={50} cy={2} rx={9} ry={14} fill="#b68460" />
          <ellipse rx={50} ry={62} fill={SK} />
          <ellipse rx={50} ry={62} fill="url(#faceL)" />
          <path d="M-52 -10Q-60 -78 0 -78Q60 -78 52 -10Q40 -52 0 -54Q-40 -52 -52 -10Z" fill="#3a2616" />
          <path d="M-50 4Q-50 62 0 74Q50 62 50 4Q44 38 0 44Q-44 38 -50 4Z" fill="#33211a" />
          <path d="M-22 28Q0 20 22 28Q0 34 -22 28Z" fill="#33211a" />
          <path d={`M-8 38Q0 ${41 + look * 2} 8 38`} stroke="#7a4636" strokeWidth={3} fill="none" strokeLinecap="round" />
          {[-19, 19].map((x) => (
            <g key={x}>
              <ellipse cx={x} cy={-6} rx={8.5} ry={7.5 * eyes} fill="#f4ead8" />
              <circle cx={x} cy={-6 + look * 3} r={4.4} fill="#241812" />
              <circle cx={x - 1.4} cy={-8 + look * 3} r={1.7} fill="#fff" />
            </g>
          ))}
          <path d="M-34 -21Q-22 -28 -8 -31M34 -21Q22 -28 8 -31" stroke="#3a2616" strokeWidth={5} fill="none" strokeLinecap="round" />
          <path d="M2 -2Q9 14 -2 18" stroke="#6b3f2a" strokeOpacity={0.5} strokeWidth={3} fill="none" strokeLinecap="round" />
        </g>
      </g>
    </g>
  );
};

const Disc: React.FC<{s: number; i: number; robe: string; hair: string; skin: string; exc: number}> = ({s, i, robe, hair, skin, exc}) => {
  const bob = Math.abs(Math.sin(s * 5 + i * 1.7)) * -16 * exc + Math.sin(s * 1.5 + i) * 2;
  const ar = exc * (0.5 + 0.5 * Math.sin(s * 6 + i * 2));
  const arL = exc * (0.5 + 0.5 * Math.sin(s * 5.2 + i * 3));
  return (
    <g transform={`translate(0 ${bob})`}>
      <ellipse cy={8} rx={130} ry={22} fill="#000" opacity={0.25} />
      <path d="M-70 -400Q-110 -200 -128 0H128Q110 -200 70 -400Q0 -430 -70 -400Z" fill={robe} stroke="#ffe0a0" strokeOpacity={0.35} strokeWidth={3} />
      <path d="M-70 -400Q-110 -200 -128 0H128Q110 -200 70 -400Q0 -430 -70 -400Z" fill="url(#shade)" />
      <path d={`M-62 -385Q-112 -320 ${-96 - arL * 14} ${-240 - arL * 200}`} stroke={robe} strokeWidth={38} fill="none" strokeLinecap="round" />
      <path d={`M62 -385Q112 -320 ${96 + ar * 14} ${-240 - ar * 200}`} stroke={robe} strokeWidth={38} fill="none" strokeLinecap="round" />
      <circle cx={-96 - arL * 14} cy={-240 - arL * 200} r={19} fill={skin} />
      <circle cx={96 + ar * 14} cy={-240 - ar * 200} r={19} fill={skin} />
      <g transform="translate(0 -515)">
        <rect x={-15} y={40} width={30} height={34} rx={9} fill={skin} />
        <ellipse rx={47} ry={58} fill={skin} />
        <ellipse rx={47} ry={58} fill="url(#faceL)" />
        <path d="M-49 -6Q-54 -72 0 -72Q54 -72 49 -6Q38 -46 0 -48Q-38 -46 -49 -6Z" fill={hair} />
        {[-17, 17].map((x) => (
          <g key={x}>
            <ellipse cx={x} cy={-4} rx={7} ry={7.5} fill="#f4ead8" />
            <circle cx={x} cy={-4} r={4} fill="#201812" />
            <circle cx={x - 1.3} cy={-6} r={1.6} fill="#fff" />
          </g>
        ))}
        <path d="M-30 -19Q-20 -26 -7 -27M30 -19Q20 -26 7 -27" stroke={hair} strokeWidth={4.5} fill="none" strokeLinecap="round" />
        <ellipse cy={30} rx={9} ry={3 + exc * 8 * Math.abs(Math.sin(s * 9 + i))} fill="#5a2a22" />
      </g>
    </g>
  );
};

const Jesus: React.FC<{s: number; ext: number; side: number}> = ({s, ext, side}) => {
  const br = Math.sin(s * 1.4) * 3;
  const H1: [number, number] = mix([68, -235], [86, -398], ext);
  const H2: [number, number] = mix([-68, -235], [66, -338], ext);
  const hand = (h: [number, number], key: string) => (
    <g key={key} transform={`translate(${h[0]} ${h[1] + br})`}>
      {[-11, -3.5, 4, 11].map((fx, i) => <ellipse key={i} cx={fx} cy={-20 + Math.abs(fx) * 0.4} rx={4.6} ry={11} fill="#e3b995" />)}
      <circle r={21} fill="#e3b995" />
      <circle r={6.5} fill="#d79b8e" opacity={0.6 * ext} />
    </g>
  );
  return (
    <g>
      <ellipse cy={-300} rx={380} ry={520} fill="url(#glowW)" opacity={0.85} />
      <ellipse cy={8} rx={160} ry={26} fill="#000" opacity={0.2} />
      <g transform={`translate(0 ${br})`}>
        <path d="M-76 -420Q-120 -200 -150 0Q0 22 150 0Q120 -200 76 -420Q0 -452 -76 -420Z" fill="url(#jRobe)" stroke="#fff6d8" strokeWidth={3} />
        <path d="M-76 -420Q-120 -200 -150 0Q0 22 150 0Q120 -200 76 -420Q0 -452 -76 -420Z" fill="url(#shade)" opacity={0.5} />
        <path d="M-80 -270Q0 -250 80 -270" stroke="#d9c9a0" strokeWidth={10} fill="none" />
        <path d="M0 -430V-20" stroke="#cdbb90" strokeOpacity={0.4} strokeWidth={3} />
        <circle cx={-58} cy={-330} r={30 * side} fill="url(#glowW)" opacity={0.95} />
      </g>
      <path d={`M-58 ${-408 + br}Q ${20 + ext * 40} ${-360 + br} ${H2[0]} ${H2[1] + br}`} stroke="#f4ecd6" strokeWidth={46} strokeLinecap="round" fill="none" />
      <path d={`M58 ${-408 + br}Q ${110 + ext * 30} ${-340 + br} ${H1[0]} ${H1[1] + br}`} stroke="#f4ecd6" strokeWidth={46} strokeLinecap="round" fill="none" />
      {hand(H2, 'h2')}
      {hand(H1, 'h1')}
      <g transform={`translate(8 ${-562 + br})`}>
        <path d="M-52 -10Q-62 -80 0 -80Q62 -80 52 -10Q64 70 46 112Q0 126 -46 112Q-64 70 -52 -10Z" fill="url(#hairJ)" />
        <path d="M-46 -40Q0 -82 46 -40" stroke="#ffe7a8" strokeOpacity={0.6} strokeWidth={4} fill="none" />
      </g>
    </g>
  );
};

const Mist: React.FC<{s: number; a: number; x: number; y: number; r?: number}> = ({s, a, x, y, r = 1}) =>
  a <= 0.01 ? null : (
    <g transform={`translate(${x} ${y}) scale(${r})`} opacity={a}>
      {Array.from({length: 7}, (_, i) => (
        <ellipse key={i} cx={Math.sin(s * 0.35 + i * 1.7) * 130 + (i - 3) * 34} cy={-300 + i * 78 + Math.cos(s * 0.3 + i) * 20} rx={200 + (i % 3) * 50} ry={95 + (i % 2) * 40} fill="url(#fog)" />
      ))}
    </g>
  );

// ---------- Escena ----------
export const Escena: React.FC = () => {
  const {s} = useS();
  const tI = en('incrédulo');
  const tJudea = en('Judea');
  const tApe = en('apedrearlo');
  const tTomas3 = en('Tomás', 3);
  const tVamos = en('vamos');
  const tMuramos = en('muramos');
  const tCreer2 = en('creer', 2);
  const tPaso = en('pasó');
  const tDisf = en('disfraza');
  const tOcho = en('Ocho');
  const tCerr = en('cerradas');
  const tEstaV = en('Tomás', 4);
  const tEntro = en('entró');
  const tOfre = en('ofreció');
  const tManos = en('manos');
  const tCost = en('costado');
  const tFij = en('fíjate');
  const tToc = en('tocara');
  const tBasto = en('bastó');
  const tSenor2 = en('Señor', 2);
  const tVolvio = en('volvió');
  const tUno = en('uno');
  const tTamp = en('tampoco');
  const tCrees = en('Crees');
  const tResp = en('Responde');
  const tSI = T(idx('Responde') + 1);

  // visibilidad de cada sitio (fundidos largos de luz)
  const roadVis = F(s, tI, 1.8) * (1 - F(s, tCreer2 - 0.05, 1.1));
  const dockVis = F(s, tCreer2 - 0.05, 1.1) * (1 - F(s, tOcho - 0.25, 1.0));
  const roomVis = s < 25 ? 1 - F(s, tI, 1.8) : F(s, tOcho - 0.25, 1.0);

  // cámara que respira y se desliza
  const K: [number, number, number, number][] = [
    [0, 1.0, 540, 980], [en('Señor'), 1.08, 420, 1260], [en('respondió'), 1.2, 790, 1180], [en('dedo'), 1.45, 820, 1230], [en('creería') - 0.4, 1.45, 820, 1200],
    [tI - 2, 1.1, 700, 1100], [tI + 0.2, 1.0, 560, 1000], [16, 1.06, 520, 1180], [tJudea, 1.12, 620, 1100], [tTomas3, 1.15, 560, 1280],
    [tVamos, 1.3, 540, 1250], [tMuramos, 1.22, 540, 1300], [tCreer2 - 0.4, 1.05, 540, 1150], [tPaso, 1.05, 540, 1050], [tDisf, 1.3, 540, 950],
    [tOcho + 0.1, 1.0, 600, 1100], [tCerr, 1.05, 640, 1100], [tEntro, 1.0, 620, 1150], [en('directo'), 1.1, 660, 1150], [tManos, 1.35, 740, 1100],
    [tFij - 0.6, 1.38, 740, 1090], [en('bien') + 0.85, 1.38, 740, 1090], [en('verlo') - 0.1, 1.55, 860, 1010], [tSenor2 - 1, 1.4, 860, 1060],
    [tSenor2 + 0.5, 1.2, 820, 1300], [tVolvio, 1.1, 720, 1250], [tTamp - 0.8, 1.0, 640, 1150], [tCrees + 0.2, 1.05, 780, 1130], [DUR, 1.14, 830, 1050],
  ];
  const kt = K.map((k) => k[0]);
  const ez = {...clamp, easing: Easing.inOut(Easing.sin)};
  const cz = interpolate(s, kt, K.map((k) => k[1]), ez);
  const cx = interpolate(s, kt, K.map((k) => k[2]), ez);
  const cy = interpolate(s, kt, K.map((k) => k[3]), ez);
  const calma = 1 - F(s, tFij - 0.3, 0.3) * (1 - F(s, en('bien') + 0.85, 0.8));
  const camT = `translate(540 960) scale(${cz * (1 + 0.012 * Math.sin(s * 0.7) * calma)}) translate(${-cx - Math.sin(s * 0.35) * 10 * calma} ${-cy - Math.cos(s * 0.28) * 8 * calma})`;

  // ---- Cuarto: estados
  const exc = s < 25 ? 0.25 + 0.75 * F(s, en('juraban') - 0.2, 0.5) * (1 - 0.7 * F(s, en('respondió'), 1)) : 0.08;
  const jesVis = F(s, tEntro + 0.1, 0.9) * (1 - F(s, tCrees, 1.4));
  const jesX = interpolate(s, [tEntro, en('puso'), en('directo'), en('directo') + 1.2], [430, 470, 470, 480], clamp);
  const jesExt = F(s, tOfre, 0.9);
  const burst = s < tEntro ? 0 : 0.75 * Math.exp(-(s - tEntro) * 2.2);
  const burstR = 1900 * F(s, tEntro, 0.9);
  const spot = F(s, tUno - 0.3, 1.2) * (1 - F(s, tCrees - 0.2, 1));
  const open = F(s, tCrees, 1.8);
  const open2 = F(s, tResp, 1.3);
  const dark = s < 25 ? 0.3 : 0.38 * (1 - jesVis * 0.9);
  const palms1 = s < 20 ? F(s, en('metía'), 0.7) * (1 - F(s, en('creería') - 0.3, 0.6)) : 0;
  const tomX = s < 25 ? 830 : interpolate(s, [en('esta') - 0.2, en('Tomás', 4) + 0.6], [1320, 870], clamp);
  const kneel = F(s, tSenor2, 1.2) * (1 - F(s, tTamp, 1.4));
  const chest = F(s, tSenor2 - 0.2, 0.6) * (1 - F(s, tTamp - 0.2, 1));
  const ext = F(s, tManos, 1.1) * (1 - F(s, tToc, 1.3));
  const cross4 = F(s, tEstaV - 0.4, 0.5) * (1 - F(s, tOfre, 0.8));
  const crossR = s < 25 ? 1 - palms1 : cross4;
  const mistA = 0.8 * F(s, tDisf, 1.5) * (1 - F(s, tSenor2, 2.3)) * (1 - 0.3 * jesVis);
  const flick = 0.5 + 0.25 * Math.sin(s * 9.3) + 0.25 * Math.sin(s * 14.1 + 1);

  const discs = [
    {x: 95, y: 1505, sc: 0.8, robe: '#5d7d93', hair: '#2e2018', skin: '#d0a07a'},
    {x: 240, y: 1488, sc: 0.84, robe: '#9a5a52', hair: '#4a3626', skin: '#b98a63'},
    {x: 385, y: 1505, sc: 0.8, robe: '#7a8a5a', hair: '#1f1814', skin: '#c99a72'},
  ];

  // ---- Camino
  const roadSpeed = 70 * (1 - 0.93 * F(s, tTomas3, 0.8));
  const wind = F(s, tMuramos - 0.1, 0.7) * (1 - F(s, tMuramos + 3.5, 2.5));
  const walk = 1 - F(s, tTomas3, 0.6);
  const ape = s - tApe;
  const cityA = 0.45 + 0.55 * F(s, tJudea, 0.9);
  const tomDir = s < tTomas3 + 0.45 ? 1 : -1;
  const raise = F(s, tVamos - 0.4, 0.7) * (1 - F(s, tMuramos + 1.2, 1.2));

  // ---- Muelle
  const agit = 4 + 22 * F(s, tPaso, 0.8) * (1 - F(s, tDisf + 0.6, 1.8));

  // brillos de transición
  const bump = (t: number, w: number, a: number) => Math.max(0, 1 - Math.abs(s - t) / w) * a;
  const flash = bump(tI + 0.9, 1.1, 0.22) + bump(tCreer2 + 0.5, 1.1, 0.2) + bump(tOcho + 0.2, 1.1, 0.22);

  return (
    <AbsoluteFill style={{background: '#10101e'}}>
      <svg width="100%" height="100%" viewBox="0 0 1080 1920">
        <defs>
          <radialGradient id="glowW"><stop stopColor="#fff0c0" stopOpacity=".9" /><stop offset=".5" stopColor="#ffd88a" stopOpacity=".28" /><stop offset="1" stopColor="#ffd88a" stopOpacity="0" /></radialGradient>
          <radialGradient id="fog"><stop stopColor="#dfe6f0" stopOpacity=".62" /><stop offset="1" stopColor="#dfe6f0" stopOpacity="0" /></radialGradient>
          <radialGradient id="faceL" cx=".35" cy=".3"><stop stopColor="#fff" stopOpacity=".28" /><stop offset="1" stopColor="#000" stopOpacity=".2" /></radialGradient>
          <linearGradient id="shade" x2="1" y2="0"><stop stopColor="#fff" stopOpacity=".12" /><stop offset=".5" stopColor="#000" stopOpacity="0" /><stop offset="1" stopColor="#000" stopOpacity=".4" /></linearGradient>
          <linearGradient id="tRobe" x2="1" y2="1"><stop stopColor="#e0b04a" /><stop offset=".55" stopColor="#c4912c" /><stop offset="1" stopColor="#8a601c" /></linearGradient>
          <linearGradient id="jRobe" x2="1" y2="1"><stop stopColor="#fffaf0" /><stop offset=".6" stopColor="#efe2c6" /><stop offset="1" stopColor="#cdbb98" /></linearGradient>
          <linearGradient id="hairJ" x2="1" y2="1"><stop stopColor="#7a5436" /><stop offset="1" stopColor="#3f2a1a" /></linearGradient>
          <linearGradient id="wall" x2="0" y2="1"><stop stopColor="#231c34" /><stop offset=".6" stopColor="#3c2c34" /><stop offset="1" stopColor="#4d362f" /></linearGradient>
          <linearGradient id="wood" x2="0" y2="1"><stop stopColor="#6a4a34" /><stop offset="1" stopColor="#38271f" /></linearGradient>
          <linearGradient id="doorLight" x2="0" y2="1"><stop stopColor="#fff6d2" /><stop offset="1" stopColor="#ffd98a" /></linearGradient>
          <linearGradient id="floorLight" x2="0" y2="1"><stop stopColor="#ffe9a8" stopOpacity=".7" /><stop offset="1" stopColor="#ffe9a8" stopOpacity="0" /></linearGradient>
          <linearGradient id="ray" x2="0" y2="1"><stop stopColor="#fff3cb" stopOpacity=".3" /><stop offset="1" stopColor="#fff3cb" stopOpacity="0" /></linearGradient>
          <linearGradient id="sky1" x2="0" y2="1"><stop stopColor="#2c2a52" /><stop offset=".55" stopColor="#c8785a" /><stop offset="1" stopColor="#f7cb86" /></linearGradient>
          <linearGradient id="sky2" x2="0" y2="1"><stop stopColor="#1d2347" /><stop offset=".6" stopColor="#6a4f78" /><stop offset="1" stopColor="#e5905e" /></linearGradient>
          <linearGradient id="sea" x2="0" y2="1"><stop stopColor="#d98a5a" /><stop offset=".25" stopColor="#4a4f7a" /><stop offset="1" stopColor="#161d3a" /></linearGradient>
          <linearGradient id="ground" x2="0" y2="1"><stop stopColor="#a47a4c" /><stop offset="1" stopColor="#5e4230" /></linearGradient>
          <linearGradient id="roadG" x2="0" y2="1"><stop stopColor="#d8ab78" /><stop offset="1" stopColor="#a8794c" /></linearGradient>
          {Array.from({length: 8}, (_, k) => <clipPath key={k} id={'sl' + k}><rect x={-400} y={1330 + k * 75} width={1900} height={75} /></clipPath>)}
        </defs>

        <g transform={camT}>
          {/* ================= CAMINO AL ATARDECER ================= */}
          <g opacity={roadVis}>
            <rect x={-500} y={-300} width={2100} height={1250} fill="url(#sky1)" />
            <ellipse cx={800} cy={890} rx={620} ry={420} fill="url(#glowW)" opacity={0.9} />
            <circle cx={800} cy={880} r={70} fill="#fff1c4" />
            <g transform={`translate(${-md(s * 6, 400)} 0)`}>
              {[0, 1].map((c) => <path key={c} d={`M${-100 + c * 1000} 900Q${150 + c * 1000} 780 ${420 + c * 1000} 850T${900 + c * 1000} 900Z`} fill="#6b4f6e" opacity={0.7} />)}
            </g>
            <g transform={`translate(${-s * 10} 0)`} opacity={cityA}>
              <path d="M560 905Q760 790 1000 850Q1180 880 1200 905Z" fill="#8a6150" />
              {Array.from({length: 10}, (_, i) => {
                const bx = 690 + i * 42, bh = 40 + ((i * 37) % 46);
                return <g key={i}><rect x={bx} y={850 - bh} width={38} height={bh + 20} fill={i % 2 ? '#d0a275' : '#c08d60'} /><rect x={bx + 12} y={850 - bh + 14} width={9} height={14} fill="#ffd27a" opacity={0.5 + 0.5 * F(s, tJudea, 1)} /></g>;
              })}
              <path d="M700 862H1112" stroke="#a97d58" strokeWidth={10} />
              <path d="M820 804Q845 760 870 804Z" fill="#e0b27c" />
              {ape > 0 && ape < 2.4 && Array.from({length: 6}, (_, i) => {
                const u = ape - i * 0.12;
                if (u < 0) return null;
                return <ellipse key={i} cx={640 - u * 70 - i * 18} cy={850 - 90 * u + 120 * u * u + i * 6} rx={8} ry={6} fill="#6f6a66" opacity={Math.max(0, 1 - ape / 2.4)} />;
              })}
            </g>
            <path d="M-50 905Q250 820 560 910Z" fill="#7a5a4a" />
            <rect x={-500} y={900} width={2100} height={1500} fill="url(#ground)" />
            <path d="M-700 1250Q540 1110 1800 1260L1800 1760Q540 1620 -700 1780Z" fill="url(#roadG)" />
            {Array.from({length: 18}, (_, i) => {
              const y = 960 + (i * 197) % 900;
              const x = md(i * 223 - s * roadSpeed * (0.4 + y / 1500), 1380) - 150;
              return <g key={i}><ellipse cx={x} cy={y} rx={14 + (i % 3) * 8} ry={6 + (i % 2) * 3} fill={i % 2 ? '#7a5a3c' : '#4f6a3c'} opacity={0.8} /></g>;
            })}
            {[0, 1, 2].map((i) => {
              const bx = [150, 400, 620][i] + 30 * i;
              return Array.from({length: 5}, (_, p) => {
                const age = md(s * 1.2 + p * 0.2 + i * 0.07, 1);
                return <circle key={i + '_' + p} cx={bx - 30 - age * 90} cy={1590 + i * 30 - age * 70} r={14 + age * 34} fill="#e7c595" opacity={0.3 * (1 - age) * (0.2 + walk)} />;
              });
            })}
            {[{x: 210, y: 1625, sc: 0.9, robe: '#5d7d93', hair: '#2e2018', skin: '#d0a07a'}, {x: 400, y: 1595, sc: 0.98, robe: '#9a5a52', hair: '#4a3626', skin: '#b98a63'}].map((d, i) => (
              <g key={i} transform={`translate(${d.x} ${d.y}) scale(${d.sc}) skewX(${Math.sin(s * 4 + i) * wind * 7})`}><Disc s={s} i={i + 3} robe={d.robe} hair={d.hair} skin={d.skin} exc={walk * 0.15} /></g>
            ))}
            <g transform={`translate(620 1570) scale(1.1)`}>
              <Tomas s={s} walk={walk} dir={tomDir} raise={raise} wind={wind} turn={Math.sin(s * 2) * 2} />
            </g>
            {/* polvo dorado y viento en 'muramos' */}
            {Array.from({length: 46}, (_, i) => {
              const sp = 140 + (i % 5) * 60;
              return <circle key={i} cx={md(i * 97 + (s - tMuramos) * sp, 1300) - 100} cy={1050 + ((i * 61) % 700) + Math.sin(s * 2 + i) * 14} r={3 + (i % 4)} fill="#ffdc8a" opacity={wind * 0.8} />;
            })}
          </g>

          {/* ================= MUELLE ================= */}
          <g opacity={dockVis}>
            <rect x={-500} y={-300} width={2100} height={1120} fill="url(#sky2)" />
            <ellipse cx={540} cy={830} rx={560} ry={300} fill="url(#glowW)" opacity={0.9} />
            <path d="M440 826A100 100 0 0 1 640 826Z" fill="#ffe3a8" />
            <rect x={-500} y={820} width={2100} height={1600} fill="url(#sea)" />
            <path d="M440 826H640L760 1500H320Z" fill="#ffdc9a" opacity={0.1} />
            {Array.from({length: 18}, (_, i) => (
              <path key={i} d={`M${60 + (i % 6) * 180 + Math.sin(s * 0.8 + i) * 30} ${850 + i * 52}q60 -16 120 0q60 16 120 0`} stroke="#ffe2b0" strokeOpacity={0.25} strokeWidth={4} fill="none" />
            ))}
            <g transform={`translate(240 ${818 + Math.sin(s * 1.1) * 4}) rotate(${Math.sin(s * 0.9) * 2})`}>
              <path d="M-50 0H50L34 18H-34Z" fill="#2a2038" /><path d="M0 0V-70L36 -8Z" fill="#3a2e4c" />
            </g>
            {[0, 1, 2].map((i) => (
              <path key={i} d={`M${md(s * 24 + i * 380, 1300) - 100} ${470 + i * 70 + Math.sin(s + i) * 12}q14 ${-12 + Math.sin(s * 6 + i) * 8} 28 0q14 ${-12 + Math.sin(s * 6 + i) * 8} 28 0`} stroke="#2b2442" strokeWidth={4} fill="none" />
            ))}
            {/* reflejo que se agita */}
            <g opacity={0.4}>
              {Array.from({length: 8}, (_, k) => (
                <g key={k} clipPath={`url(#sl${k})`}>
                  <g transform={`translate(${540 + Math.sin(s * 3.2 + k * 1.3) * agit} 1330) scale(.95 -.95)`}><Tomas s={s} look={0.9} /></g>
                </g>
              ))}
            </g>
            <path d="M-600 1170H1700L1780 1250H-700Z" fill="#8c6a48" />
            <path d="M-700 1250H1780V1300H-700Z" fill="url(#wood)" />
            {Array.from({length: 14}, (_, i) => <path key={i} d={`M${-60 + i * 88} 1172L${-90 + i * 94} 1250`} stroke="#4b3426" strokeWidth={4} opacity={0.6} />)}
            {[100, 420, 780, 1010].map((x) => <rect key={x} x={x} y={1296} width={26} height={230} fill="#2f2119" opacity={0.7} />)}
            <g transform="translate(540 1220) scale(.95)">
              <Tomas s={s} look={0.9} />
            </g>
            <Mist s={s} a={mistA} x={540} y={1180} r={1.25} />
          </g>

          {/* ================= CUARTO (gancho, reencuentro y bucle) ================= */}
          <g opacity={roomVis}>
            <rect x={-500} y={-300} width={2100} height={1900} fill="url(#wall)" />
            {Array.from({length: 14}, (_, i) => <path key={i} d={`M${-20 + i * 90} -100V1480`} stroke="#000" opacity={0.08} strokeWidth={3} />)}
            {/* ventana nocturna */}
            <rect x={90} y={470} width={290} height={470} rx={140} fill="#1b2a58" stroke="#6b5a4d" strokeWidth={16} />
            {Array.from({length: 12}, (_, i) => <circle key={i} cx={130 + (i * 53) % 220} cy={540 + (i * 79) % 330} r={2.2} fill="#fff" opacity={0.4 + 0.5 * Math.abs(Math.sin(s * 1.2 + i))} />)}
            <circle cx={290} cy={600} r={32} fill="#f3ecd0" opacity={0.85} />
            <path d="M235 470V940M90 760H380" stroke="#6b5a4d" strokeWidth={10} />
            {/* puerta */}
            <path d="M690 1480V830Q690 610 855 610Q1020 610 1020 830V1480Z" fill="#6b5a4d" />
            <path d="M712 1480V836Q712 640 855 640Q998 640 998 836V1480Z" fill="url(#doorLight)" opacity={0.15 + 0.85 * open} />
            <g transform={`translate(712 0) scale(${1 - 0.86 * open} 1) translate(-712 0)`}>
              <path d="M712 1480V836Q712 640 855 640Q998 640 998 836V1480Z" fill="url(#wood)" />
              {[0, 1, 2, 3].map((i) => <path key={i} d={`M${712 + 71 * (i + 1)} 640V1480`} stroke="#241810" strokeWidth={4} />)}
              <path d="M712 1100H998M712 800H998" stroke="#2c1d13" strokeWidth={10} />
              <circle cx={960} cy={1090} r={11} fill="#d6a85a" />
            </g>
            <Flame x={660} y={930} s={s} i={4} k={0.95} />
            <path d="M648 940Q660 970 690 960L700 940Z" fill="#b5793c" />
            {/* lámpara colgante */}
            <path d="M250 -200V690" stroke="#8a6a44" strokeWidth={5} />
            <Lamp x={235} y={715} s={s} i={1} />
            {/* piso */}
            <rect x={-500} y={1480} width={2100} height={900} fill="#3b2b2a" />
            {Array.from({length: 7}, (_, i) => <path key={i} d={`M0 ${1500 + i * 70}H1080M${i * 180 - 40} 1480L${i * 230 - 260} 1920`} stroke="#241817" strokeWidth={3} opacity={0.5} />)}
            <path d="M690 1480H1020L1250 1920H300Z" fill="url(#floorLight)" opacity={open * 0.85} />

            {/* discípulos tras la mesa */}
            {discs.map((d, i) => (
              <g key={i} transform={`translate(${d.x} ${d.y}) scale(${d.sc})`}><Disc s={s} i={i} robe={d.robe} hair={d.hair} skin={d.skin} exc={exc} /></g>
            ))}
            {/* mesa */}
            <path d="M-10 1470H470L530 1565H-70Z" fill="#7a5638" stroke="#a47a54" strokeWidth={3} />
            <path d="M-70 1565H530V1610H-70Z" fill="url(#wood)" />
            <path d="M-40 1610V1830M490 1610V1830" stroke="#2c1d13" strokeWidth={30} />
            <Lamp x={205} y={1462} s={s} i={2} />
            <ellipse cx={95} cy={1488} rx={42} ry={13} fill="#d9b27a" /><ellipse cx={95} cy={1478} rx={36} ry={10} fill="#ecc68e" />
            <path d="M330 1470L342 1440H372L384 1470Z" fill="#a98156" />
            <ellipse cx={170} cy={1400} rx={170 * F(s, en('Señor'), 0.9) * (1 - F(s, tI - 1, 1))} ry={200 * F(s, en('Señor'), 0.9) * (1 - F(s, tI - 1, 1))} fill="url(#glowW)" opacity={0.7} />

            {/* Jesús: solo de espaldas y sus manos, nunca el rostro */}
            <g opacity={jesVis}>
              <g transform={`translate(${jesX} 1620) scale(1.42)`}><Jesus s={s} ext={jesExt} side={F(s, tCost, 0.7)} /></g>
            </g>

            {/* Tomás */}
            <g transform={`translate(${tomX} ${s < 25 ? 1600 : 1618}) scale(1.35)`}>
              <Tomas s={s} cross={crossR} palms={palms1} ext={ext} kneel={kneel} chest={chest} dir={s < 25 ? 1 : -1}
                look={s < 25 ? palms1 : 0} eyes={1 + 0.14 * F(s, tBasto, 0.5) * (1 - F(s, tSenor2, 1))}
                turn={s < 25 ? -9 * golpe(s, en('respondió'), 14, 3) - 6 * golpe(s, en('creería'), 14, 3) : 0} />
            </g>
            {/* la llama tiembla en su cara */}
            <ellipse cx={tomX - 40} cy={885} rx={150} ry={170} fill="url(#glowW)" opacity={(s < 25 ? 0.4 : 0.22) * flick} />
            <Mist s={s} a={mistA} x={tomX} y={1520} r={1.5} />

            {/* oscuridad, estallido de luz y foco en uno solo */}
            <rect x={-500} y={-300} width={2100} height={2900} fill="#0b0714" opacity={dark} />
            <circle cx={855} cy={1050} r={burstR} fill="url(#glowW)" opacity={Math.min(1, burst * 1.4)} />
            <rect x={-500} y={-300} width={2100} height={2900} fill="#fff3cf" opacity={burst * 0.45 + jesVis * 0.06} />
            <rect x={-500} y={-300} width={2100} height={2900} fill="#0b0714" opacity={spot * 0.5} />
            <circle cx={700} cy={1150} r={700} fill="url(#glowW)" opacity={spot * 0.8} />
            <ellipse cx={855} cy={1050} rx={420 * open2} ry={760 * open2} fill="url(#glowW)" opacity={open * 0.7} />
          </g>
        </g>

        {/* rayos y polvo de luz que flotan, siempre en movimiento */}
        <path d={`M${120 + Math.sin(s * 0.16) * 40} -80L${620 + Math.sin(s * 0.2) * 30} 1980 L${340} 1980L${-60} 300Z`} fill="url(#ray)" opacity={0.28} />
        <path d={`M${700 + Math.sin(s * 0.13) * 50} -80L1180 1500L${900 + Math.sin(s * 0.18) * 30} 1700L${520} 200Z`} fill="url(#ray)" opacity={0.2} />
        {Array.from({length: 44}, (_, i) => (
          <circle key={i} cx={md(i * 131 + Math.sin(s * 0.2 + i) * 20, 1080)} cy={md(i * 97 - s * (8 + (i % 3) * 5), 1920)} r={2 + (i % 4)} fill="#fff0c9" opacity={0.2 + 0.18 * Math.sin(s * 0.7 + i)} />
        ))}
        <rect width={1080} height={1920} fill="#ffe9b8" opacity={flash} />
        <rect width={1080} height={1920} fill="url(#vig)" />
        <defs><radialGradient id="vig" cx=".5" cy=".5" r=".75"><stop offset=".55" stopColor="#000" stopOpacity="0" /><stop offset="1" stopColor="#000" stopOpacity=".55" /></radialGradient></defs>
      </svg>
    </AbsoluteFill>
  );
};
